(function(){
  const $=id=>document.getElementById(id);
  const results=$('ai-results'), status=$('ai-status'), tree=$('ai-tree'), raw=$('ai-raw');
  let latest=null, candidates=[];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const split=s=>String(s||'').split(/[\n,;]+/).map(x=>x.trim()).filter(Boolean);
  function node(n,final=false){
    // Kept only as a fallback for old API responses. Normal responses use
    // tree_html generated by the exact classic renderer in app.py.
    if(!n)return '';
    if(typeof n==='string')return `<div class="node"><div class="node-card"><div class="node-name">${esc(n)}</div></div></div>`;
    const children=[n.parent1,n.parent2].filter(Boolean);
    let h=`<div class="node${final?' root':''}" data-path="ai-fallback"><div class="node-card"><div class="node-name">${esc(n.name||'Monstre')}</div></div>`;
    if(children.length)h+=`<div class="recipe-block"><div class="parents">${children.map(c=>node(c)).join('')}</div></div>`;
    return h+'</div>';
  }
  function attachTreeInteractions(){
    tree.querySelectorAll('.node-toggle').forEach(btn=>{
      btn.onclick=e=>{
        e.stopPropagation();
        const n=btn.closest('.node'); if(!n)return;
        const collapsed=n.classList.toggle('collapsed');
        btn.textContent=collapsed?'+':'−';
        btn.title=collapsed?'Afficher la suite de l\'arbre':'Masquer la suite de l\'arbre';
      };
    });
    tree.querySelectorAll('.node-card').forEach(card=>{
      card.onclick=e=>{
        if(e.target.closest('.node-toggle'))return;
        const n=card.closest('.node'); if(!n)return;
        n.classList.toggle('validated');
      };
    });
  }
  function selectCandidate(i){
    candidates.forEach((c,j)=>c.el.classList.toggle('active',i===j));
    const c=candidates[i].data;
    tree.innerHTML=c.tree_html || node(c.tree,true);
    attachTreeInteractions();
    $('ai-result-title').textContent=`${c.monster} — solution ${i+1}`;
    $('ai-result-subtitle').textContent=`Score ${c.score} • ${c.metrics?.syntheses??'—'} synthèses • ${c.metrics?.wild_captures??'—'} captures`;
  }
  function render(data){
    latest=data;candidates=(data.candidates||[]).map(c=>({data:c}));
    results.classList.remove('ai-hidden');
    const box=$('ai-candidates');box.innerHTML='';
    candidates.forEach((c,i)=>{const b=document.createElement('button');b.className='ai-candidate';b.innerHTML=`<strong>${esc(c.data.monster||'Solution '+(i+1))}</strong><small>Score ${esc(c.data.score)} · synthèses ${esc(c.data.metrics?.syntheses??'—')} · captures ${esc(c.data.metrics?.wild_captures??'—')}</small>`;b.onclick=()=>selectCandidate(i);c.el=b;box.appendChild(b)});
    raw.textContent=JSON.stringify(data,null,2);
    if(candidates.length)selectCandidate(0);else{tree.innerHTML='<p>Aucune solution trouvée avec ces contraintes.</p>'; $('ai-result-subtitle').textContent='';}
  }
  $('ai-build').onclick=async()=>{
    const monster=$('ai-monster').value.trim();
    const talents=[...document.querySelectorAll('.ai-talent')].map(x=>x.value.trim()).filter(Boolean);
    if(!monster){status.textContent='⚠️ Choisis un monstre final.';return;}
    if(new Set(talents.map(x=>x.toLowerCase())).size!==talents.length){status.textContent='⚠️ Les talents doivent être distincts.';return;}
    status.textContent='🧠 Recherche en cours…';$('ai-build').disabled=true;
    try{
      const payload={monster,talents,zone:$('ai-zone').value.trim(),goal:$('ai-goal').value,owned:split($('ai-owned').value),excluded_wild:split($('ai-excluded').value),include_eggs:$('ai-eggs').checked,top:Number($('ai-top').value),max_calls:30000};
      const r=await fetch('/api/ai/plan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok||data.error)throw Error(data.error||'Erreur serveur');render(data);status.textContent=`✅ ${data.candidates?.length||0} solution(s) trouvée(s).`;
    }catch(e){status.textContent='❌ '+e.message}finally{$('ai-build').disabled=false}
  };
  $('ai-copy').onclick=()=>navigator.clipboard?.writeText(JSON.stringify(latest,null,2));
})();
